"""Finish v3 with its reviewed 14-second film-to-timeline camera handoff."""
from pathlib import Path
import subprocess,json,hashlib,sys
root=Path(__file__).resolve().parents[1];name=sys.argv[1];assert name in ['landscape','portrait']
out=root/'out/creative-polish-v3';source=out/f'{name}-picture.mp4';patch=out/f'{name}-film-reveal.mp4';text_patch=out/f'{name}-text-controls.mp4';audio=out/'audio-delivery.m4a';dest=out/f'{name}.mp4';temporary=out/f'{name}-finishing.mp4'
def video_probe(p):return next(s for s in json.loads(subprocess.check_output(['ffprobe','-v','error','-show_streams','-of','json',str(p)],text=True))['streams'] if s['codec_type']=='video')
v=video_probe(source);q=video_probe(patch);z=video_probe(text_patch);assert int(z['nb_frames'])==360 and z['avg_frame_rate']=='30/1',z;assert int(v['nb_frames'])==8940 and v['avg_frame_rate']=='30/1',v;assert int(q['nb_frames'])==420 and q['avg_frame_rate']=='30/1',q
assert v.get('color_space') in [None,'unknown','smpte170m','bt470bg'],v.get('color_space')
# Composite only the reviewed same-revision handoff. Every other scene retains
# the complete v3 picture render; music is continuous on its own 298-second clock.
graph='[0:v]trim=end_frame=3330,setpts=PTS-STARTPTS[a];[1:v]setpts=PTS-STARTPTS[b];[0:v]trim=start_frame=3690:end_frame=5520,setpts=PTS-STARTPTS[c];[2:v]setpts=PTS-STARTPTS[d];[0:v]trim=start_frame=5940:end_frame=8940,setpts=PTS-STARTPTS[e];[a][b][c][d][e]concat=n=5:v=1:a=0,zscale=matrixin=170m:matrix=709:rangein=limited:range=limited[v]'
subprocess.run(['ffmpeg','-hide_banner','-y','-i',str(source),'-i',str(text_patch),'-i',str(patch),'-i',str(audio),'-filter_complex',graph,'-map','[v]','-map','3:a:0','-c:v','libx264','-preset','fast','-crf','17','-pix_fmt','yuv420p','-color_primaries','bt709','-color_trc','iec61966-2-1','-colorspace','bt709','-color_range','tv','-c:a','copy','-movflags','+faststart','-t','298',str(temporary)],check=True);temporary.replace(dest)
receipt={'picture_source':str(source.relative_to(root)),'picture_frames':8940,'duration':298,'fps':30,'reviewed_text_controls':{'source':str(text_patch.relative_to(root)),'frame_range':[3330,3690],'frames':360,'same_revision':True},'reviewed_handoff':{'source':str(patch.relative_to(root)),'frame_range':[5520,5940],'frames':420,'same_revision':True},'audio_source':str(audio.relative_to(root)),'audio_sha256':hashlib.sha256(audio.read_bytes()).hexdigest(),'output':str(dest.relative_to(root)),'bytes':dest.stat().st_size,'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'color':'Explicit-range zscale converts the default BT.601 matrix to BT.709, preserving BT.709 primaries and original sRGB transfer. Limited range; not merely relabeled.','encode':'H.264 CRF17 / fast / yuv420p. Verified AAC fast 320kbps stereo 48kHz copied without re-encoding; faststart. Output atomically replaces the temporary encoding file.'}
(out/f'{name}-finish.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt,indent=2))
